import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
// 가정: 취소는 신청·승인 상태에서만 가능하다 (전환표에 취소 가능 상태가 없음)
const CANCELABLE = ['신청', '승인'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function bad(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function nameOf(value: unknown): string {
  if (typeof value !== 'string' || value.trim() === '' || value.length > 200) {
    throw bad('원인행위 명칭을 200자 이내로 입력해 주세요.');
  }
  return value;
}

function idOf(value: unknown, label: string): string {
  const n = typeof value === 'string' && value.trim() !== '' ? Number(value) : value;
  if (typeof n !== 'number' || !Number.isInteger(n) || n <= 0) {
    throw bad(`${label}을(를) 선택해 주세요.`);
  }
  return String(n);
}

function optionalIdOf(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return idOf(value, label);
}

function amountOf(value: unknown): string {
  const n = typeof value === 'string' && value.trim() !== '' ? Number(value) : value;
  if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
    throw bad('원인행위 금액은 0보다 큰 숫자로 입력해 주세요.');
  }
  return String(n);
}

interface Input {
  name: string;
  projectId: string;
  budgetAccountId: string;
  partnerId: string | null;
  amount: string;
}

function readInput(data: Record<string, unknown>): Input {
  return {
    name: nameOf(data['name']),
    projectId: idOf(data['projectId'], '프로젝트'),
    budgetAccountId: idOf(data['budgetAccountId'], '예산과목'),
    partnerId: optionalIdOf(data['partnerId'], '거래처'),
    amount: amountOf(data['amount']),
  };
}

type Db = {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
};

async function checkReferences(db: Db, input: Input): Promise<void> {
  const projects = await db.query(
    'SELECT project_id FROM project WHERE project_id = CAST(:id AS bigint)',
    { id: input.projectId },
  );
  if (projects.length === 0) {
    throw new ApiError(404, 'NOT_FOUND', '선택한 프로젝트를 찾을 수 없습니다.');
  }
  const accounts = await db.query(
    'SELECT budget_account_id FROM budget_account WHERE budget_account_id = CAST(:id AS bigint)',
    { id: input.budgetAccountId },
  );
  if (accounts.length === 0) {
    throw new ApiError(404, 'NOT_FOUND', '선택한 예산과목을 찾을 수 없습니다.');
  }
  if (input.partnerId !== null) {
    const partners = await db.query(
      'SELECT partner_id FROM partner WHERE partner_id = CAST(:id AS bigint)',
      { id: input.partnerId },
    );
    if (partners.length === 0) {
      throw new ApiError(404, 'NOT_FOUND', '선택한 거래처를 찾을 수 없습니다.');
    }
  }
}

@Controller('api/v1')
export class FnSfr00404Controller {
  @Post('/budget-commitments')
  @HttpCode(200)
  async createBudgetCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const input = readInput(data);
    return transaction(async (db) => {
      await checkReferences(db, input);
      const rows = await db.query(
        `INSERT INTO budget_commitment (name, project_id, budget_account_id, partner_id, amount, approval_status, created_at, updated_at)
         VALUES (:name, CAST(:projectId AS bigint), CAST(:budgetAccountId AS bigint), CAST(:partnerId AS bigint), CAST(:amount AS numeric), '신청', now(), now())
         RETURNING budget_commitment_id AS "budgetCommitmentId", approval_status AS "approvalStatus"`,
        input as unknown as Record<string, unknown>,
      );
      return rows[0];
    });
  }

  @Get('/budget-commitments')
  async listBudgetCommitments(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const projectId = optionalIdOf(query['projectId'], '프로젝트');
    const budgetAccountId = optionalIdOf(query['budgetAccountId'], '예산과목');
    const pageNo = Number(query['page'] ?? 0);
    const sizeNo = Number(query['size'] ?? DEFAULT_SIZE);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(sizeNo) || sizeNo < 1) {
      throw bad('page 또는 size 값이 올바르지 않습니다.');
    }
    const size = Math.min(sizeNo, MAX_SIZE);
    return transaction(async (db) => {
      const params = { projectId, budgetAccountId, limit: size, offset: pageNo * size };
      const where = `(CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))
         AND (CAST(:budgetAccountId AS bigint) IS NULL OR budget_account_id = CAST(:budgetAccountId AS bigint))`;
      const items = await db.query(
        `SELECT budget_commitment_id AS "budgetCommitmentId", name AS "name", project_id AS "projectId",
                budget_account_id AS "budgetAccountId", partner_id AS "partnerId", amount AS "amount",
                approval_status AS "approvalStatus"
         FROM budget_commitment
         WHERE ${where}
         ORDER BY budget_commitment_id DESC
         LIMIT :limit OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM budget_commitment WHERE ${where}`,
        params,
      );
      return {
        items: items.map((r: any) => ({ ...r, amount: Number(r.amount) })),
        page: pageNo,
        size,
        total: Number(counts[0].total),
      };
    });
  }

  @Put('/budget-commitments/:budgetCommitmentId')
  async updateBudgetCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['budgetCommitmentId'], '원인행위');
    const data = checks.inputOf(req.body);
    const input = readInput(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM budget_commitment WHERE budget_commitment_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'BUDGET_COMMITMENT_NOT_FOUND', '원인행위를 찾을 수 없습니다.');
      }
      if (found[0].approvalStatus === '승인') {
        throw new ApiError(409, 'BUDGET_COMMITMENT_APPROVED', '승인된 원인행위는 수정할 수 없습니다. 승인 취소 절차를 거쳐 주세요.');
      }
      await checkReferences(db, input);
      const rows = await db.query(
        `UPDATE budget_commitment
         SET name = :name, project_id = CAST(:projectId AS bigint), budget_account_id = CAST(:budgetAccountId AS bigint),
             partner_id = CAST(:partnerId AS bigint), amount = CAST(:amount AS numeric), updated_at = now()
         WHERE budget_commitment_id = CAST(:id AS bigint)
         RETURNING budget_commitment_id AS "budgetCommitmentId"`,
        { ...input, id },
      );
      return rows[0];
    });
  }

  @Post('/budget-commitments/:budgetCommitmentId/cancel')
  @HttpCode(200)
  async cancelBudgetCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['budgetCommitmentId'], '원인행위');
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM budget_commitment WHERE budget_commitment_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'BUDGET_COMMITMENT_NOT_FOUND', '원인행위를 찾을 수 없습니다.');
      }
      if (!CANCELABLE.includes(found[0].approvalStatus)) {
        throw new ApiError(409, 'BUDGET_COMMITMENT_NOT_CANCELABLE', '취소할 수 없는 상태의 원인행위입니다.');
      }
      const rows = await db.query(
        `UPDATE budget_commitment
         SET approval_status = '승인 취소', updated_at = now()
         WHERE budget_commitment_id = CAST(:id AS bigint)
         RETURNING approval_status AS "approvalStatus"`,
        { id },
      );
      return rows[0];
    });
  }
}

