import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr00404Page({ role, notify }: PageProps) {
  const [projectId, setProjectId] = useState<number | string>('');
  const [budgetAccountId, setBudgetAccountId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({});

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/budget-commitments', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [role, applied, pageNo],
  );

  const setField = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const openCreate = () => {
    setForm({});
    setCreating(true);
  };

  const openEdit = (row: Row) => {
    setForm({
      name: row.name,
      projectId: row.projectId,
      budgetAccountId: row.budgetAccountId,
      partnerId: row.partnerId ?? '',
      amount: row.amount,
    });
    setEditing(row);
  };

  const validate = () => {
    if (!String(form.name ?? '').trim()) {
      throw new Error('원인행위 명칭을 입력해 주세요.');
    }
    if (!form.projectId) {
      throw new Error('프로젝트를 선택해 주세요.');
    }
    if (!form.budgetAccountId) {
      throw new Error('예산과목을 선택해 주세요.');
    }
    if (form.amount === '' || form.amount === undefined || form.amount === null) {
      throw new Error('원인행위 금액을 입력해 주세요.');
    }
  };

  const body = (): Row => ({
    name: form.name,
    projectId: form.projectId,
    budgetAccountId: form.budgetAccountId,
    partnerId: form.partnerId === '' ? undefined : form.partnerId,
    amount: form.amount,
  });

  const submitCreate = async () => {
    validate();
    await call('POST', '/budget-commitments', role, body());
    notify('원인행위를 등록했습니다.');
    setCreating(false);
    reload();
  };

  const submitEdit = async () => {
    validate();
    await call('PUT', `/budget-commitments/${editing?.budgetCommitmentId}`, role, body());
    notify('원인행위를 수정했습니다.');
    setEditing(null);
    setSelected(null);
    reload();
  };

  const submitCancel = async () => {
    await call('POST', `/budget-commitments/${selected?.budgetCommitmentId}/cancel`, role, {});
    notify('원인행위를 취소했습니다.');
    setSelected(null);
    reload();
  };

  const canEdit = (row: Row) => row.approvalStatus !== '승인';
  const canCancel = (row: Row) => row.approvalStatus === '신청' || row.approvalStatus === '승인';

  const fields = (
    <>
      <Field label='원인행위 명칭' required wide>
        <TextInput value={form.name} onChange={(v) => setField('name', v)} />
      </Field>
      <Field label='프로젝트' required>
        <LookupSelect table='project' role={role} value={form.projectId} onChange={(v) => setField('projectId', v)} />
      </Field>
      <Field label='예산과목' required>
        <LookupSelect table='budget_account' role={role} value={form.budgetAccountId} onChange={(v) => setField('budgetAccountId', v)} />
      </Field>
      <Field label='거래처'>
        <LookupSelect table='partner' role={role} value={form.partnerId} onChange={(v) => setField('partnerId', v)} />
      </Field>
      <Field label='원인행위 금액' required>
        <NumberInput value={form.amount} onChange={(v) => setField('amount', v)} />
      </Field>
    </>
  );

  if (selected) {
    return (
      <div className='doc'>
        <button className='ghost' onClick={() => setSelected(null)}>목록으로</button>
        <section className='box'>
          <h2>원인행위 내용</h2>
          <Pairs
            items={[
              ['원인행위 ID', String(selected.budgetCommitmentId)],
              ['원인행위 명칭', String(selected.name)],
              ['프로젝트', <RefName table='project' role={role} value={selected.projectId} />],
              ['예산과목', <RefName table='budget_account' role={role} value={selected.budgetAccountId} />],
              ['거래처', selected.partnerId ? <RefName table='partner' role={role} value={selected.partnerId} /> : '-'],
              ['원인행위 금액', <Num value={selected.amount} />],
              ['승인 상태', <Badge value={selected.approvalStatus} />],
            ]}
          />
        </section>
        <section className='box'>
          <h2>처리</h2>
          {canEdit(selected) && <button onClick={() => openEdit(selected)}>수정</button>}
          {canCancel(selected) && (
            <Form onSubmit={submitCancel} submit='원인행위 취소' danger note='취소하면 승인 상태가 승인 취소로 바뀌며 되돌릴 수 없습니다.' />
          )}
          {!canEdit(selected) && !canCancel(selected) && <p>이 상태에서는 처리할 수 있는 작업이 없습니다.</p>}
        </section>
        {editing && (
          <Drawer title='원인행위 수정' onClose={() => setEditing(null)}>
            <Form onSubmit={submitEdit} submit='저장'>
              {fields}
            </Form>
          </Drawer>
        )}
      </div>
    );
  }

  return (
    <div className='doc'>
      <section className='box'>
        <h2>원인행위</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied({ projectId, budgetAccountId });
          }}
          onReset={() => {
            setProjectId('');
            setBudgetAccountId('');
            setPageNo(0);
            setApplied({});
          }}
        >
          <Field label='프로젝트'>
            <LookupSelect table='project' role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label='예산과목'>
            <LookupSelect table='budget_account' role={role} value={budgetAccountId} onChange={setBudgetAccountId} />
          </Field>
        </Filters>
        {error && <ErrorText text={error} />}
        <Band total={data?.total}>
          <button onClick={openCreate}>원인행위 등록</button>
        </Band>
        <DataTable
          columns={[
            { key: 'name', label: '원인행위 명칭' },
            { key: 'projectId', label: '프로젝트', render: (r) => <RefName table='project' role={role} value={r.projectId} /> },
            { key: 'budgetAccountId', label: '예산과목', render: (r) => <RefName table='budget_account' role={role} value={r.budgetAccountId} /> },
            { key: 'amount', label: '원인행위 금액', render: (r) => <Num value={r.amount} /> },
            { key: 'approvalStatus', label: '승인 상태', render: (r) => <Badge value={r.approvalStatus} /> },
          ]}
          rows={data?.items ?? []}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : '아직 등록한 원인행위가 없습니다. 원인행위 등록 버튼으로 시작해 주세요.'}
        />
        <Pager page={pageNo} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {creating && (
        <Drawer title='원인행위 등록' onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit='등록'>
            {fields}
          </Form>
        </Drawer>
      )}
    </div>
  );
}
